// Applica le modifiche: aggiunta fonti anche dal form di modifica.
// Uso: salva nella cartella RADICE del progetto e lancia:  node applica-modifiche.js
import { writeFileSync, mkdirSync, readFileSync } from 'fs'
import { dirname } from 'path'

const files = {
  "src/utils/fusioneFonti.js": '',
  "src/components/PannelloFonte.jsx": '',
  "src/components/PannelloFonte.css": '',
  "src/components/ChatNuovoViaggio.jsx": '',
  "src/components/FormViaggio.jsx": '',
  "src/pages/Home.css": '',
}

for (const [percorso, b64] of Object.entries(files)) {
  mkdirSync(dirname(percorso), { recursive: true })
  writeFileSync(percorso, Buffer.from(b64, 'base64'))
  console.log('scritto:', percorso)
}

const form = readFileSync('src/components/FormViaggio.jsx', 'utf8')
console.log(form.includes('PannelloFonte')
  ? '\nVERIFICA OK — pannello fonte agganciato al form di modifica.'
  : '\nATTENZIONE — stai eseguendo una versione vecchia dello script.')
console.log('Ora: git add . && git commit -m "fonti anche in modifica" && git push')